public void testKeySet2() {
    ExtendedProperties p = new ExtendedProperties();
    p.put("a", "foo");
    p.put("b", "bar");
    p.put("c", "bar");

    Iterator it = p.getKeys();
    assertEquals("a", (String) it.next());
    assertEquals("b", (String) it.next());
    assertEquals("c", (String) it.next());
    assertFalse(it.hasNext());
}
